    // Initialize a 2D array to store the minimum time required to collect all apples and return to node 0
    int[][] minTime = new int[n][n];

    // Initialize a 2D array to store the number of apples in each subtree
    int[][] numApples = new int[n][n];

    // Initialize a 1D array to store the minimum time required to collect all apples in each subtree
    int[] minTimeSubtree = new int[n];

    // Initialize a 1D array to store the number of apples in each subtree
    int[] numApplesSubtree = new int[n];

    // Initialize the minimum time required to collect all apples and return to node 0
    int minTimeTotal = 0;

    // Loop through each edge and calculate the minimum time required to collect all apples and return to node 0
    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];

        // Calculate the minimum time required to collect all apples in the subtree rooted at node u
        minTimeSubtree[u] = Math.max(minTimeSubtree[u], minTimeSubtree[v] + 1);

        // Calculate the number of apples in the subtree rooted at node u
        numApplesSubtree[u] += numApplesSubtree[v] + (hasApple[v] ? 1 : 0);

        // Update the minimum time required to collect all apples and return to node 0
        minTimeTotal = Math.max(minTimeTotal, minTimeSubtree[u] + numApplesSubtree[u]);
    }

    return minTimeTotal;
}

public String sortString(String s) {
    // Step 1: Sort the string in ascending order
    char[] sortedChars = s.toCharArray();
    Arrays.sort(sortedChars);

    // Step 2: Reverse the order of the sorted characters
    StringBuilder result = new StringBuilder();
    for (int i = sortedChars.length - 1; i >= 0; i--) {
        result.append(sortedChars[i]);
    }

    // Step 3: Append the largest character to the result
    result.append(sortedChars[0]);

    // Step 4: Reverse the order of the result
    StringBuilder finalResult = new StringBuilder();
    for (int i = result.length() - 1; i >= 0; i--) {
        finalResult.append(result.charAt(i));
    }

    return finalResult.toString();
}

