public static int findSmallestInteger(int n) {
    int smallestInteger = -1;
    String nStr = String.valueOf(n);
    for (int i = 0; i < nStr.length(); i++) {
        for (int j = i + 1; j < nStr.length(); j++) {
            if (nStr.charAt(i) > nStr.charAt(j)) {
                String temp = nStr.substring(i, j);
                nStr = nStr.substring(0, i) + nStr.substring(j, nStr.length());
                nStr = nStr.substring(0, j) + temp + nStr.substring(j + 1, nStr.length());
            }
        }
    }
    if (nStr.length() > 0) {
        smallestInteger = Integer.parseInt(nStr);
    }
    return smallestInteger;
}

