public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    if (x1 == x2 && y1 == y2) {
        return false;
    }
    if (x2 == x3 && y2 == y3) {
        return false;
    }
    if (x1 == x3 && y1 == y3) {
        return false;
    }

    int dx1 = x2 - x1;
    int dy1 = y2 - y1;
    int dx2 = x3 - x1;
    int dy2 = y3 - y1;

    return (dx1 * dy2 - dy1 * dx2) != 0;
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    for (int i = 1; i < n; i++) {
        int min = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = min;
        if (min == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }
        if (min == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }
        if (min == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int maxLength = 0;
    int currentLength = 0;
    char currentChar = '\0';
    for (char c : s.toCharArray()) {
        if (c == currentChar) {
            currentLength++;
        } else {
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
            currentLength = 1;
            currentChar = c;
        }
    }
    return maxLength;
}

